CREATE TABLE newcomer_stage (id uuid PRIMARY KEY,church_id uuid NOT NULL REFERENCES church(id),name text NOT NULL,sort_order integer NOT NULL,terminal boolean NOT NULL,active boolean NOT NULL,UNIQUE(church_id,id),UNIQUE(church_id,name));
CREATE TABLE newcomer_journey (id uuid PRIMARY KEY,church_id uuid NOT NULL,member_id uuid NOT NULL,stage_id uuid NOT NULL,assignee_id uuid NOT NULL,due_on date,completed_at timestamptz,version integer NOT NULL DEFAULT 1,UNIQUE(church_id,id),UNIQUE(church_id,member_id),FOREIGN KEY(church_id,member_id) REFERENCES member(church_id,id),FOREIGN KEY(church_id,stage_id) REFERENCES newcomer_stage(church_id,id),FOREIGN KEY(church_id,assignee_id) REFERENCES app_user(church_id,id));
CREATE TABLE newcomer_change (id uuid PRIMARY KEY,church_id uuid NOT NULL,journey_id uuid NOT NULL,from_stage text,to_stage text NOT NULL,assignee_id uuid NOT NULL,due_on date,actor_id uuid NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(church_id,journey_id) REFERENCES newcomer_journey(church_id,id),FOREIGN KEY(church_id,assignee_id) REFERENCES app_user(church_id,id),FOREIGN KEY(church_id,actor_id) REFERENCES app_user(church_id,id),UNIQUE(journey_id,version));
CREATE TRIGGER newcomer_history_immutable BEFORE UPDATE OR DELETE ON newcomer_change FOR EACH ROW EXECUTE FUNCTION prevent_operation_history_change();
CREATE INDEX newcomer_due_idx ON newcomer_journey(church_id,completed_at,due_on);
INSERT INTO permission(code) VALUES ('newcomer.read'),('newcomer.write');
INSERT INTO role_permission(role_id,permission_code) SELECT role_id,p.code FROM role_permission r CROSS JOIN (VALUES ('newcomer.read'),('newcomer.write')) p(code) WHERE r.permission_code='identity.manage';
